import{_ as d,o as a,c as e,ag as s}from"./chunks/framework.BLV0JUXI.js";const u=JSON.parse('{"title":"11.1 基础入门：工具类应用选型与权限矩阵","description":"扫码、定位、存储、文件、分享能力在四端的支持矩阵与取舍。","frontmatter":{"title":"11.1 基础入门：工具类应用选型与权限矩阵","description":"扫码、定位、存储、文件、分享能力在四端的支持矩阵与取舍。","tags":["工具类","系统能力","权限矩阵","实战"],"version":"3.2.0","difficulty":1},"headers":[],"relativePath":"guide/11-tools/basics.md","filePath":"guide/11-tools/basics.md","lastUpdated":1793196275000}'),n={name:"guide/11-tools/basics.md"};function i(r,t,o,l,p,c){return a(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="_11-1-基础入门-工具类应用选型与权限矩阵" tabindex="-1">11.1 基础入门：工具类应用选型与权限矩阵 <a class="header-anchor" href="#_11-1-基础入门-工具类应用选型与权限矩阵" aria-label="Permalink to &quot;11.1 基础入门：工具类应用选型与权限矩阵&quot;">​</a></h1><p>工具类应用（扫码、记账、笔记、证件照、习惯打卡等）的特点是：<strong>重系统能力、轻实时业务、页面少而链路短</strong>。它的技术风险主要不在 UI，而在「能力是否支持、权限能否拿到、审核能否通过」。</p><h2 id="典型工具箱的功能域" tabindex="-1">典型工具箱的功能域 <a class="header-anchor" href="#典型工具箱的功能域" aria-label="Permalink to &quot;典型工具箱的功能域&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能域</th><th>代表功能</th><th>核心能力</th></tr></thead><tbody><tr><td>识别</td><td>二维码/条形码、拍照识物</td><td><code>uni.scanCode</code>、相机、图片选择</td></tr><tr><td>位置</td><td>打卡、附近、轨迹</td><td><code>uni.getLocation</code>、地图组件、后台定位</td></tr><tr><td>存储</td><td>笔记、账本、离线数据</td><td>Storage / SQLite / 文件系统</td></tr><tr><td>文件</td><td>导出 PDF/CSV、保存图片</td><td>文件 API、分享面板</td></tr><tr><td>系统交互</td><td>复制、振动、亮屏、网络状态</td><td>clipboard / vibrator / device</td></tr><tr><td>通知</td><td>打卡提醒</td><td>App 推送 / 小程序订阅消息</td></tr></tbody></table><h2 id="能力支持矩阵-立项前必须核对" tabindex="-1">能力支持矩阵（立项前必须核对） <a class="header-anchor" href="#能力支持矩阵-立项前必须核对" aria-label="Permalink to &quot;能力支持矩阵（立项前必须核对）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>H5</th><th>微信小程序</th><th>App</th></tr></thead><tbody><tr><td>扫码</td><td>❌ 原生（需自定义识别）</td><td>✅ <code>uni.scanCode</code></td><td>✅ <code>uni.scanCode</code></td></tr><tr><td>定位（前台）</td><td>✅ 需 HTTPS 授权</td><td>✅ 需声明用途与类目</td><td>✅ 运行时权限</td></tr><tr><td>后台定位</td><td>❌</td><td>⚠️ 受限，需特定类目</td><td>✅（需声明权限并审核）</td></tr><tr><td>拍照/相册</td><td>getUserAPI/input</td><td><code>uni.chooseImage</code> + 授权</td><td>原生能力</td></tr><tr><td>保存到相册</td><td>❌（仅下载）</td><td><code>saveImageToPhotosAlbum</code></td><td>原生</td></tr><tr><td>本地数据库</td><td>IndexedDB</td><td>Storage 10MB（大数据用插件/云）</td><td>SQLite</td></tr><tr><td>文件读写</td><td>File System Access 受限</td><td>FileSystemManager（沙盒）</td><td>完整文件系统</td></tr><tr><td>系统分享</td><td>Web Share 受限</td><td>转发/分享到朋友圈</td><td><code>uni.share</code> 全渠道</td></tr><tr><td>推送通知</td><td>❌</td><td>订阅消息（用户主动订阅）</td><td>厂商通道推送</td></tr><tr><td>剪贴板</td><td>✅（部分浏览器需交互触发）</td><td>✅</td><td>✅</td></tr><tr><td>振动/蜂鸣</td><td>navigator.vibrate</td><td>✅</td><td>✅</td></tr><tr><td>NFC/蓝牙</td><td>Web Bluetooth 有限</td><td>部分支持（指定类目）</td><td>✅ 插件生态完整</td></tr></tbody></table><p>立项 SOP：</p><ol><li>列出功能清单，逐项查矩阵，标注「原生支持 / 需插件 / 不支持」。</li><li>不支持的平台<strong>直接做产品降级</strong>（如 H5 隐藏扫码入口，改为上传二维码图片识别）。</li><li>检查小程序类目与审核要求：定位、相册等敏感能力与服务类目强绑定。</li></ol><h2 id="权限设计原则" tabindex="-1">权限设计原则 <a class="header-anchor" href="#权限设计原则" aria-label="Permalink to &quot;权限设计原则&quot;">​</a></h2><p>参考 <a href="/uniapp-tutorial-pages/guide/07-adapt/practice">7.3 权限封装</a>，工具类应用要更克制：</p><ul><li><strong>用时申请</strong>：不要在启动页一次性索要全部权限，在用户点击对应功能时才申请。</li><li><strong>解释价值</strong>：系统弹框前先用业务弹窗说明「为什么需要」，教育类工具能显著提升授权率。</li><li><strong>拒绝可活</strong>：拒绝定位后仍可手动选择城市；拒绝相册后仍可拍照。永远给替代路径。</li><li><strong>权限清单最小化</strong>：manifest 只声明实际使用的权限，多一个权限就多一分审核风险（尤其 iOS）。</li></ul><h2 id="数据与离线优先策略" tabindex="-1">数据与离线优先策略 <a class="header-anchor" href="#数据与离线优先策略" aria-label="Permalink to &quot;数据与离线优先策略&quot;">​</a></h2><p>工具类应用常被在地铁、地下室等弱网使用，架构应<strong>离线优先（offline-first）</strong>：</p><ol><li>所有用户数据先写本地，UI 立即响应。</li><li>有账号体系时再做后台同步，冲突策略提前定义（最后写入胜出/按字段合并）。</li><li>导出功能保证「没有网络也能拿到数据」，这是工具类产品的信任底线。</li></ol><h2 id="页面与工程规划" tabindex="-1">页面与工程规划 <a class="header-anchor" href="#页面与工程规划" aria-label="Permalink to &quot;页面与工程规划&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pages/</span></span>
<span class="line"><span>├─ index/index          工具宫格首页</span></span>
<span class="line"><span>├─ scan/index           扫码</span></span>
<span class="line"><span>├─ location/index       定位打卡</span></span>
<span class="line"><span>├─ records/index        记录列表</span></span>
<span class="line"><span>├─ records/edit         记录编辑</span></span>
<span class="line"><span>└─ settings/index       设置（权限管理、导出、关于）</span></span>
<span class="line"><span>subPackages:</span></span>
<span class="line"><span>└─ pages/export          导出/分享等低频功能</span></span>
<span class="line"><span>src/</span></span>
<span class="line"><span>├─ platforms/           能力适配层（7.3 已建立的模式）</span></span>
<span class="line"><span>├─ services/db.ts       本地数据库统一接口</span></span>
<span class="line"><span>└─ stores/records.ts    记录数据 store</span></span></code></pre></div><h2 id="练习" tabindex="-1">练习 <a class="header-anchor" href="#练习" aria-label="Permalink to &quot;练习&quot;">​</a></h2><ol><li>为你想做的工具列 10 个功能，完成能力矩阵标注，并写出至少 3 处平台降级方案。</li><li>检查三个目标平台的审核文档，列出本产品需要在 manifest 声明的全部权限及用途文案。</li><li>设计离线数据模型：哪些表、主键、与云端同步的字段（updatedAt/deleted）。</li></ol><p>下一篇 <a href="/uniapp-tutorial-pages/guide/11-tools/advanced">11.2 扫码、定位、存储、文件与分享实现</a> 给出核心能力代码。</p>`,19)])])}const g=d(n,[["render",i]]);export{u as __pageData,g as default};
